    trust = raw_record["trust"]
    _validate_header_trust(trust)
    digest = raw_record["digest"]
    if not crypto.is_hex64(digest):
        raise _Failure(ERR_INPUT)
    document = {
        "state": state,
        "proofs": proofs,
        "auth": {
            "key_version": raw_auth["key_version"],
            "signature": raw_auth["signature"],
        },
    }
    return {
        "generation": raw_record["generation"],
        "anchor": {
            key: raw_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS
        },
        "accounts": list(batch_accounts),
        "account": account,
        "proof": proof,
        "document": document,
        "trust": trust,
        "digest": digest,
    }


def verify_state_anchors_export(document: object) -> dict:
    """Verify a self-contained historical state-anchor export offline.

    No path or local trust material is supplied. Structural, key-order,
    raw-type, hex, mixed-key, non-finite-number or JSON-serialization defects
    return ``input``. Every embedded batch is then replayed with
    :func:`verify_state_proofs`; an unknown signer version or bad Ed25519
    signature returns ``auth``. Anchor bindings, account sets, Merkle paths,
    same-height anchor consistency, repeated-pair proof consistency, ordering
    and either digest tampering return ``integrity``.

    Success returns ``{"ok": True, "generation", "heights", "accounts",
    "records"}`` with ``records`` as ascending ``{"height", "account"}``
    summaries. Nothing is read or written and no malformed input raises.
    """
    try:
        _stable_canonical_json_bytes(document)
        if (
            not isinstance(document, dict)
            or tuple(document.keys()) != STATE_ANCHORS_EXPORT_KEYS
        ):
            raise _Failure(ERR_INPUT)
        if not _is_int(document["v"]) or document["v"] != (
            STATE_ANCHORS_EXPORT_VERSION
        ):
            raise _Failure(ERR_INPUT)
        generation = document["generation"]
        if not _is_int(generation) or generation < 0:
            raise _Failure(ERR_INPUT)
        heights, accounts = _validate_state_anchors_export_filter(
            document["heights"], document["accounts"]
        )
        raw_records = document["records"]
        if not isinstance(raw_records, list):
            raise _Failure(ERR_INPUT)
        records = [
            _parse_state_anchors_export_record(raw) for raw in raw_records
        ]

        anchors_by_height: dict[int, dict] = {}
        proofs_by_pair: dict[tuple[int, str], dict] = {}
        previous_pair: tuple[int, str] | None = None

        for record in records:
            pair = (
                record["anchor"]["height"],
                record["account"],
            )
            if previous_pair is not None and pair < previous_pair:
                raise _Failure(ERR_INTEGRITY)
            previous_pair = pair

            if record["generation"] != generation or generation < 1:
                raise _Failure(ERR_INTEGRITY)
            if pair[0] not in heights or pair[1] not in accounts:
                raise _Failure(ERR_INTEGRITY)

            result = verify_state_proofs(
                record["document"], record["accounts"], record["trust"]
            )
            if not result.get("ok"):
                raise _Failure(result["error"])

            state = record["document"]["state"]
            anchor = record["anchor"]
            if anchor != {
                "height": state["height"],
                "block_hash": state["block_hash"],
                "state_root": state["state_root"],
            }:
                raise _Failure(ERR_INTEGRITY)

            proof_by_account = {
                proof["account"]: proof
                for proof in record["document"]["proofs"]
            }
            if proof_by_account.get(record["account"]) != record["proof"]:
                raise _Failure(ERR_INTEGRITY)

            known_anchor = anchors_by_height.get(pair[0])
            if known_anchor is not None and known_anchor != anchor:
                raise _Failure(ERR_INTEGRITY)
            anchors_by_height.setdefault(pair[0], anchor)

            known_proof = proofs_by_pair.get(pair)
            if known_proof is not None and known_proof != record["proof"]:
                raise _Failure(ERR_INTEGRITY)
            proofs_by_pair.setdefault(pair, record["proof"])

            if _state_anchors_export_record_digest(record) != record["digest"]:
                raise _Failure(ERR_INTEGRITY)

        expected_digest = _state_anchors_export_digest(document)
        if expected_digest != document["digest"]:
            raise _Failure(ERR_INTEGRITY)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}

    return {
        "ok": True,
        "generation": generation,
        "heights": heights,
        "accounts": accounts,
        "records": [
            {
                "height": record["anchor"]["height"],
                "account": record["account"],
            }
            for record in records
        ],
    }


# -- offline cross-export coverage and consistency audit ---------------------

STATE_ANCHORS_AUDIT_PAIR_KEYS = ("height", "account")
STATE_ANCHORS_AUDIT_RESULT_KEYS = ("ok", "verified", "missing", "conflicts")


def _validate_state_anchors_audit_pairs(expected_pairs: object) -> list[tuple]:
    """Validate the pinned non-empty distinct ``(height, account)`` list."""
    if not isinstance(expected_pairs, list) or not expected_pairs:
        raise _Failure(ERR_INPUT)
    pairs: list[tuple[int, str]] = []
    for raw_pair in expected_pairs:
        if (
            not isinstance(raw_pair, dict)
            or tuple(raw_pair.keys()) != STATE_ANCHORS_AUDIT_PAIR_KEYS
        ):
            raise _Failure(ERR_INPUT)
        height = raw_pair["height"]
        account = raw_pair["account"]
        if not _is_int(height) or height < 0:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(account):
            raise _Failure(ERR_INPUT)
        pairs.append((height, account))
    if len(set(pairs)) != len(pairs):
        raise _Failure(ERR_INPUT)
    return pairs


def audit_state_anchors_exports(documents: object, expected_pairs: object) -> dict:
    """Audit multiple self-contained state-anchor exports offline.

    ``documents`` is the source-ordered, non-empty list of export documents
    produced by :func:`export_state_anchors`; ``expected_pairs`` is a
    non-empty list of pinned ``{"height", "account"}`` combinations (each
    height a non-boolean non-negative integer and each account a
    64-lowercase-hex string, with no duplicate combination). Every export is
    first fully verified with :func:`verify_state_anchors_export`; the hits
    are then merged by height and account. Equivalent records repeated within
    one source count once.

    Success returns ``{"ok": True, "verified", "missing", "conflicts"}`` in
    that key order; every group holds ``{"height", "account"}`` entries
    stably sorted by height then account. A pinned combination is ``verified``
    when every source carrying it agrees on block hash, state root and the
    full account-proof content and every source agrees on that height's
    anchor; ``missing`` when no source carries it at all (a source simply
    lacking a record never causes a conflict); ``conflicts`` when sources
    that carry it disagree on the anchor or proof content, or sources
    disagree on the anchor at that height.

    Failure returns only ``{"ok": False, "error": category}``: ``input`` for
    bad parameters, document structure, key order, types, hex, mixed keys,
    non-finite numbers or non-stably-serializable content; ``auth`` for an
    unknown audit signature version or a shape-valid but failing Ed25519
    signature; ``integrity`` for a tampered export digest, ordering, account
    set, anchor binding, Merkle path or same-height anchor. Nothing is read
    or written, arguments are never mutated and nothing is raised; the call
    is a pure function of its inputs.
    """
    try:
        if not isinstance(documents, list) or not documents:
            return {"ok": False, "error": ERR_INPUT}
        pairs = _validate_state_anchors_audit_pairs(expected_pairs)
        _stable_canonical_json_bytes(documents)
        _stable_canonical_json_bytes(expected_pairs)

        # Per source: pair -> (anchor, proof), with equivalent duplicate
        # records inside one export counted once; each source contributes
        # one anchor vote per height (same-height anchors within a verified
        # export are already guaranteed identical).
        pair_evidence: list[dict[tuple, tuple]] = []
        anchor_votes_by_height: dict[int, list[dict]] = {}
        for raw_document in documents:
            verdict = verify_state_anchors_export(raw_document)
            if not verdict.get("ok"):
                return {"ok": False, "error": verdict["error"]}
            records = [
                _parse_state_anchors_export_record(raw_record)
                for raw_record in raw_document["records"]
            ]
            evidence: dict[tuple, tuple] = {}
            source_anchors: dict[int, dict] = {}
            for record in records:
                anchor = {
                    key: record["anchor"][key]
                    for key in STATE_ANCHOR_ANCHOR_KEYS
                }
                height = anchor["height"]
                source_anchors.setdefault(height, anchor)
                pair = (height, record["account"])
                evidence.setdefault(pair, (anchor, record["proof"]))
            for height, anchor in source_anchors.items():
                anchor_votes_by_height.setdefault(height, []).append(anchor)
            pair_evidence.append(evidence)

        verified: list[dict] = []
        missing: list[dict] = []
        conflicts: list[dict] = []
        for height, account in sorted(pairs):
            entry = {"height": height, "account": account}
            hits = [
                evidence[(height, account)]
                for evidence in pair_evidence
                if (height, account) in evidence
            ]
            if not hits:
                missing.append(entry)
                continue
            pair_anchors = [anchor for anchor, _proof in hits]
            proofs = [proof for _anchor, proof in hits]
            first_anchor = pair_anchors[0]
            divergent = any(anchor != first_anchor for anchor in pair_anchors)
            divergent = divergent or any(
                proof != proofs[0] for proof in proofs
            )
            height_votes = anchor_votes_by_height.get(height, [])
            divergent = divergent or (
                any(vote != first_anchor for vote in height_votes)
            )
            if divergent:
                conflicts.append(entry)
            else:
                verified.append(entry)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        return {"ok": False, "error": ERR_INPUT}

    return {
        "ok": True,
        "verified": verified,
        "missing": missing,
        "conflicts": conflicts,
    }


def audit_state_anchors_archives(paths: object, expected_pairs: object) -> dict:
    """Audit multiple local batch state-anchor archives offline.

    ``paths`` is the source-ordered, non-empty list of non-empty distinct
    archive path strings maintained by :func:`record_state_anchors`;
    ``expected_pairs`` is a non-empty list of pinned
    ``{"height", "account"}`` combinations (each height a non-boolean
    non-negative integer and each account a 64-lowercase-hex string, with
    no duplicate combination). Every existing archive is strictly loaded
    under the batch state-anchor archive rules (shape, key order, digest,
    proof replay and internal-conflict checks); a missing archive is an
    empty source, not an error. Equivalent duplicate records inside one
    source count once. The call never reads service state and never
    writes, cleans or rearranges an archive.

    Success returns ``{"ok": True, "verified", "missing", "conflicts"}``
    in that key order; every group holds ``{"height", "account"}``
    entries stably sorted by height then account regardless of the input
    path order. A pinned combination is ``verified`` when every source
    carrying it agrees on block hash, state root and the full
    account-proof content and every source agrees on that height's
    anchor; ``missing`` when no source carries it at all (a source
    lacking the archive or the record never causes a conflict);
    ``conflicts`` when sources that carry it disagree on the anchor or
    proof content, or sources disagree on the anchor at that height.

    Failure returns only ``{"ok": False, "error": category}``: ``input``
    for bad parameters or non-stably-serializable input (path-list or
    pair-list shape, types, hex or duplicate combinations); ``state`` for
    an archive failing its strict parse, key-order, digest, proof-replay
    or internal-conflict checks; ``io`` for a read failure. Nothing is
    raised; identical inputs yield identical results across repeated,
    concurrent and post-restart calls.
    """
    try:
        if (
            not isinstance(paths, list)
            or not paths
            or any(not isinstance(path, str) or not path for path in paths)
            or len(set(paths)) != len(paths)
        ):
            return {"ok": False, "error": ERR_INPUT}
        pairs = _validate_state_anchors_audit_pairs(expected_pairs)
        _stable_canonical_json_bytes(paths)
        _stable_canonical_json_bytes(expected_pairs)

        pair_evidence: list[dict[tuple, tuple]] = []
